namespace BlazorApp.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly Lock _lock = new();
    private readonly List<Notification> _notifications = [];

    public NotificationService()
    {
        // Seed with some initial notifications.
        _notifications.AddRange(
        [
            MakeNotification("Welcome to the app!"),
            MakeNotification("Your profile has been set up."),
            MakeNotification("Check out the new dashboard features."),
        ]);
    }

    /// <summary>Returns all notifications with an Id greater than <paramref name="sinceId"/>.</summary>
    public Task<List<Notification>> GetNotificationsAsync(int sinceId = 0)
    {
        lock (_lock)
        {
            var result = _notifications.Where(n => n.Id > sinceId).ToList();
            return Task.FromResult(result);
        }
    }

    /// <summary>Simulates new notifications arriving over time.</summary>
    public void SimulateIncoming()
    {
        lock (_lock)
        {
            _notifications.Add(MakeNotification(PickRandomMessage()));
        }
    }

    private Notification MakeNotification(string message)
    {
        return new Notification(_nextId++, message, DateTime.UtcNow);
    }

    private static string PickRandomMessage()
    {
        string[] pool =
        [
            "You have a new follower.",
            "Your report is ready to download.",
            "Scheduled maintenance tonight at 11 PM.",
            "New comment on your post.",
            "Your subscription renews tomorrow.",
            "A team member mentioned you.",
        ];
        return pool[Random.Shared.Next(pool.Length)];
    }
}

@page "/notifications"
@rendermode InteractiveServer
@using BlazorApp.Services
@inject NotificationService Svc
@implements IAsyncDisposable

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    @if (notifications is not null)
    {
        <span class="badge bg-primary rounded-pill ms-2">@notifications.Count</span>
    }
</h1>

@if (notifications is null)
{
    <p><em>Loading…</em></p>
}
else if (notifications.Count == 0)
{
    <p>No notifications yet.</p>
}
else
{
    <ul class="list-group">
        @foreach (var n in notifications)
        {
            <li class="list-group-item d-flex justify-content-between align-items-start">
                <span>@n.Message</span>
                <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
            </li>
        }
    </ul>
}

@code {
    [PersistentState]
    public List<Notification>? notifications { get; set; }

    private int lastSeenId;
    private CancellationTokenSource? cts;

    protected override async Task OnInitializedAsync()
    {
        // ??= ensures we only fetch when the value wasn't restored from prerender state.
        notifications ??= await Svc.GetNotificationsAsync();
        lastSeenId = notifications.LastOrDefault()?.Id ?? 0;
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // OnAfterRender is never called during prerender, so the
            // polling loop only starts once the page is truly interactive.
            cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken token)
    {
        while (!token.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), token);

            Svc.SimulateIncoming();

            var newer = await Svc.GetNotificationsAsync(lastSeenId);
            if (newer.Count > 0)
            {
                notifications!.AddRange(newer);
                lastSeenId = newer[^1].Id;
                await InvokeAsync(StateHasChanged);
            }
        }
    }

    public async ValueTask DisposeAsync()
    {
        if (cts is not null)
        {
            await cts.CancelAsync();
            cts.Dispose();
        }
    }
}

