+    protected override async Task OnInitializedAsync()
+    {
+        // ??= ensures we only fetch when the value wasn't restored from prerender state.
+        notifications ??= await Svc.GetNotificationsAsync();
+        lastSeenId = notifications.LastOrDefault()?.Id ?? 0;
+    }
+
+    protected override void OnAfterRender(bool firstRender)
+    {
+        if (firstRender)
+        {
+            // OnAfterRender is never called during prerender, so the
+            // polling loop only starts once the page is truly interactive.
+            cts = new CancellationTokenSource();
+            _ = PollForNotificationsAsync(cts.Token);
+        }
+    }
+
+    private async Task PollForNotificationsAsync(CancellationToken token)
+    {
+        while (!token.IsCancellationRequested)
+        {
+            await Task.Delay(TimeSpan.FromSeconds(5), token);
+
+            Svc.SimulateIncoming();
+
+            var newer = await Svc.GetNotificationsAsync(lastSeenId);
+            if (newer.Count > 0)
+            {
+                notifications!.AddRange(newer);
+                lastSeenId = newer[^1].Id;
+                await InvokeAsync(StateHasChanged);
+            }
+        }
+    }
+
+    public async ValueTask DisposeAsync()
+    {
+        if (cts is not null)
+        {
+            await cts.CancelAsync();
+            cts.Dispose();
+        }
+    }
+}
